const API_URL="/api",adminLoginView=document.getElementById("adminLoginView"),adminDashboardView=document.getElementById("adminDashboardView"),adminLoginForm=document.getElementById("adminLoginForm"),adminLogoutBtn=document.getElementById("adminLogoutBtn"),bookingsTableBody=document.getElementById("bookingsTableBody"),partnersTableBody=document.getElementById("partnersTableBody"),toast=document.getElementById("toast"),ADMIN_EMAIL="admin@gmail.com";function showToast(t,e="success"){toast.textContent=t,toast.className=`toast show ${e}`,setTimeout(()=>{toast.classList.remove("show")},3e3)}function checkAdminAuthState(){localStorage.getItem("adminToken")?(adminLoginView.classList.add("hidden"),adminDashboardView.classList.remove("hidden"),fetchBookings(),fetchPartnerApplications(),fetchFeedback()):(adminLoginView.classList.remove("hidden"),adminDashboardView.classList.add("hidden"))}async function fetchBookings(){try{const t=localStorage.getItem("adminToken"),e=await fetch("/api/bookings",{headers:{Authorization:`Bearer ${t}`}});if(!e.ok)throw new Error("Failed to fetch bookings");const n=await e.json();if(bookingsTableBody.innerHTML="",0===n.length)return void(bookingsTableBody.innerHTML='<tr><td colspan="6" style="text-align:center;">No bookings found.</td></tr>');n.forEach(t=>{const e=document.createElement("tr");e.innerHTML=`\n                <td>${t.date}</td>\n                <td><strong>${t.name}</strong></td>\n                <td><a href="tel:${t.phone}">${t.phone}</a></td>\n                <td>${t.service}</td>\n                <td>${t.address}</td>\n                <td><span class="status-badge">${t.status||"Pending"}</span></td>\n            `,bookingsTableBody.appendChild(e)})}catch(t){console.error("Error fetching bookings: ",t),showToast("Failed to fetch bookings.","error")}}async function fetchFeedback(){try{const t=localStorage.getItem("adminToken"),e=await fetch("/api/feedback",{headers:{Authorization:`Bearer ${t}`}});if(!e.ok)throw new Error("Failed to fetch feedback");const n=await e.json(),o=document.getElementById("feedbackTableBody");if(o.innerHTML="",0===n.length)return void(o.innerHTML='<tr><td colspan="3" style="text-align:center;">No feedback received yet.</td></tr>');n.forEach(t=>{const e=document.createElement("tr");let n="";for(let e=1;e<=5;e++)e<=t.rating?n+='<i class="fa-solid fa-star" style="color: #f6ad55; margin-right: 2px;"></i>':n+='<i class="fa-regular fa-star" style="color: #cbd5e0; margin-right: 2px;"></i>';const a=t.createdAt?new Date(t.createdAt).toLocaleDateString():"N/A";e.innerHTML=`\n                <td>${a}</td>\n                <td>${n} (${t.rating}/5)</td>\n                <td>${t.comment||"N/A"}</td>\n            `,o.appendChild(e)})}catch(t){console.error("Error fetching feedback: ",t)}}async function fetchPartnerApplications(){try{const t=localStorage.getItem("adminToken"),e=await fetch("/api/partner",{headers:{Authorization:`Bearer ${t}`}});if(!e.ok)throw new Error("Failed to fetch partner applications");const n=await e.json();if(partnersTableBody.innerHTML="",0===n.length)return void(partnersTableBody.innerHTML='<tr><td colspan="5" style="text-align:center;">No applications found.</td></tr>');n.forEach(t=>{const e=document.createElement("tr"),n=t.createdAt?new Date(t.createdAt).toLocaleDateString():"N/A";e.innerHTML=`\n                <td>${n}</td>\n                <td><strong>${t.name}</strong></td>\n                <td><a href="tel:${t.phone}">${t.phone}</a></td>\n                <td>${t.skill}</td>\n                <td><span class="status-badge" style="background-color: #28a745; color: white;">${t.status||"New Applicant"}</span></td>\n            `,partnersTableBody.appendChild(e)})}catch(t){console.error("Error fetching partner applications: ",t),showToast("Failed to fetch partner applications.","error")}}checkAdminAuthState(),adminLoginForm.addEventListener("submit",async t=>{t.preventDefault();const e=document.getElementById("adminEmail").value,n=document.getElementById("adminPassword").value;if(e===ADMIN_EMAIL)try{const t=await fetch("/api/auth/admin/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:e,password:n})}),o=await t.json();t.ok?(localStorage.setItem("adminToken",o.token),showToast("Welcome Admin"),checkAdminAuthState()):showToast(o.error||"Login failed","error")}catch(t){showToast(t.message,"error")}else showToast("Access Denied. Admins only.","error")}),adminLogoutBtn.addEventListener("click",()=>{localStorage.removeItem("adminToken"),showToast("Logged out"),checkAdminAuthState()});